"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useState } from "react";
import { ArrowRight, Shield } from "react-feather";
import { Button, Flex, Input, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import BorrowConfirmModal from "./components/BorrowConfirmModal";
import BorrowReviewModal from "./components/BorrowReviewModal";
const Container = styled(Flex, {
  flexDirection: "column",
  gap: "$spacing16",
  width: "100%",
  maxWidth: 480,
  "$platform-web": {
    position: "sticky",
    top: "95px"
  }
});
const TabButton = styled(Button, {
  alignSelf: "flex-start",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  py: "$spacing12",
  px: "$spacing16",
  borderWidth: 0,
  hoverStyle: { backgroundColor: "$surface3Hovered" }
});
const Card = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  position: "relative"
});
const InputField = styled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "48px",
  fontWeight: "400",
  color: "$neutral1",
  width: "100%",
  textAlign: "left",
  placeholderTextColor: "$neutral3",
  height: "auto",
  lineHeight: "56px"
});
const MaxButton = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing12"
});
const ActionButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  py: "$spacing24",
  marginTop: "$spacing8",
  variants: {
    disabled: {
      true: {
        backgroundColor: "$surface3",
        color: "$neutral2",
        cursor: "not-allowed"
      },
      false: {
        backgroundColor: "$accent1",
        color: "$white",
        hoverStyle: { backgroundColor: "$accent1Hovered" },
        pressStyle: { backgroundColor: "$accent1Pressed" }
      }
    }
  }
});
const ShieldIcon = styled(Flex, {
  backgroundColor: "$surface4",
  borderRadius: "$roundedFull",
  width: 20,
  height: 20,
  alignItems: "center",
  justifyContent: "center",
  marginLeft: "$spacing4"
});
export default function BorrowInterface() {
  const [collateralAmount, setCollateralAmount] = useState("");
  const [borrowAmount, setBorrowAmount] = useState("");
  const [isReviewOpen, setIsReviewOpen] = useState(false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const colors = useSporeColors();
  const collateralToken = { symbol: "USDC", balance: 8.84, price: 1, id: "usdc_addr_mock" };
  const borrowToken = { symbol: "DEGEN", balance: 0, price: 0.02, id: "degen_addr_mock" };
  const liquidationLtv = 62.5;
  const rate = 14.69;
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const parsedBorrow = parseFloat(borrowAmount) || 0;
  const collateralUsd = parsedCollateral * collateralToken.price;
  const borrowUsd = parsedBorrow * borrowToken.price;
  const ltv = 0;
  const isFormValid = parsedCollateral > 0 || parsedBorrow > 0;
  const actionText = isFormValid ? "Supply collateral" : "Enter an amount";
  const handleConfirm = () => {
    setIsReviewOpen(false);
    setIsConfirmOpen(true);
  };
  return <Container>
      {
    /* Tab */
  }
      <Flex mb="$spacing8">
        <TabButton>
          <Text variant="buttonLabel2">Borrow</Text>
        </TabButton>
      </Flex>

      {
    /* Supply Collateral Card */
  }
      <Card>
        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text variant="body2" color="$neutral2">
            Supply Collateral {collateralToken.symbol}
          </Text>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id)]}
    size={20}
  />
        </Flex>

        <InputField
    placeholder="0.00"
    value={collateralAmount}
    onChangeText={setCollateralAmount}
    placeholderTextColor="$neutral3"
  />

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mt="$spacing4">
          <Text variant="body3" color={collateralUsd > 0 ? "$neutral1" : "$neutral3"}>
            ${collateralUsd.toFixed(2)}
          </Text>
          <Flex flexDirection="row" gap="$gap8" alignItems="center">
            <Text variant="body3" color="$neutral2">
              {collateralToken.balance.toFixed(2)} {collateralToken.symbol}
            </Text>
            <MaxButton onPress={() => setCollateralAmount(collateralToken.balance.toString())}>
              <Text variant="buttonLabel4" color="$neutral2">
                MAX
              </Text>
            </MaxButton>
          </Flex>
        </Flex>
      </Card>

      {
    /* Borrow Card */
  }
      <Card>
        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text variant="body2" color="$neutral2">
            Borrow {borrowToken.symbol}
          </Text>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id)]}
    size={20}
  />
        </Flex>

        <InputField
    placeholder="0.00"
    value={borrowAmount}
    onChangeText={setBorrowAmount}
    placeholderTextColor="$neutral3"
  />

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mt="$spacing4">
          <Text variant="body3" color="$neutral3">
            ${borrowUsd.toFixed(2)}
          </Text>
          <Flex flexDirection="row" gap="$gap8" alignItems="center">
            <Text variant="body3" color="$neutral2">
              {borrowToken.balance.toFixed(2)} {borrowToken.symbol}
            </Text>
            <MaxButton onPress={() => setBorrowAmount("100")}>
              <Text variant="buttonLabel4" color="$neutral2">
                MAX
              </Text>
            </MaxButton>
          </Flex>
        </Flex>
      </Card>

      {
    /* Info Card */
  }
      <Card>
        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id)]}
    size={20}
  />
            <Text variant="body2" color="$neutral2">
              Collateral ({collateralToken.symbol})
            </Text>
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              0.00
            </Text>
            {parsedCollateral > 0 && <ArrowRight size={14} color={colors.neutral3.val} />}
            {parsedCollateral > 0 && <Text variant="body2" color="$neutral1">
                {parsedCollateral}
              </Text>}
          </Flex>
        </InfoRow>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id)]}
    size={20}
  />
            <Text variant="body2" color="$neutral2">
              Loan ({borrowToken.symbol})
            </Text>
          </Flex>
          <Text variant="body2" color="$neutral1">
            0.00
          </Text>
        </InfoRow>

        <InfoRow>
          <Text variant="body2" color="$neutral2">
            LTV
          </Text>
          <Text variant="body2" color="$neutral1">
            {ltv}%
          </Text>
        </InfoRow>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center">
            <Text variant="body2" color="$neutral2">
              Liquidation LTV
            </Text>
            <ShieldIcon>
              <Shield size={10} color={colors.neutral2.val} fill={colors.neutral2.val} />
            </ShieldIcon>
          </Flex>
          <Text variant="body2" color="$neutral1">
            {liquidationLtv}%
          </Text>
        </InfoRow>

        <InfoRow style={{ marginBottom: 0 }}>
          <Text variant="body2" color="$neutral2">
            Rate
          </Text>
          <Text variant="body2" color="$neutral1">
            {rate}%
          </Text>
        </InfoRow>
      </Card>

      <ActionButton disabled={!isFormValid} onPress={() => setIsReviewOpen(true)}>
        {actionText}
      </ActionButton>

      <BorrowReviewModal
    isOpen={isReviewOpen}
    onClose={() => setIsReviewOpen(false)}
    onConfirm={handleConfirm}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={collateralToken}
    borrowToken={borrowToken}
  />

      <BorrowConfirmModal
    isOpen={isConfirmOpen}
    onClose={() => setIsConfirmOpen(false)}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={collateralToken}
    borrowToken={borrowToken}
  />
    </Container>;
}
